:root {
  --bg: #1e1e2e;
  --surface: #2a2a3c;
  --surface-hover: #35354a;
  --text: #e0e0e0;
  --accent: #f5a623;
  --accent-hover: #ffb84d;
  --accent-pressed: #d48a1a;
  --card-back: #4a4a6a;
  --card-back-hover: #5a5a7a;
  --card-back-pressed: #3a3a5a;
  --matched: #4caf50;
  --focus: #f5a623;
  --radius: 12px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.game {
  width: 100%;
  max-width: 520px;
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.game-header {
  text-align: center;
  margin-bottom: 20px;
}

h1 {
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.subtitle {
  font-size: 1rem;
  color: #aaa;
  margin-top: 4px;
}

.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  gap: 12px;
}

.moves {
  font-size: 1.1rem;
  font-weight: 600;
}

.move-count {
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.btn {
  background: var(--accent);
  color: #1e1e2e;
  border: none;
  border-radius: 8px;
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:active {
  background: var(--accent-pressed);
  transform: scale(0.97);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.win-message {
  text-align: center;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--matched);
  margin-bottom: 16px;
  padding: 12px;
  background: rgba(76, 175, 80, 0.12);
  border-radius: 8px;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
}

.card {
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  background: var(--card-back);
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0;
  padding: 0;
  position: relative;
  overflow: hidden;
}

.card:hover:not(.matched):not(.flipped) {
  background: var(--card-back-hover);
}

.card:active:not(.matched):not(.flipped) {
  background: var(--card-back-pressed);
  transform: scale(0.96);
}

.card:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  z-index: 1;
}

.card.flipped,
.card.matched {
  background: var(--card-color, var(--card-back));
  cursor: default;
}

.card.matched {
  box-shadow: inset 0 0 0 3px rgba(255, 255, 255, 0.4);
  animation: matchPulse 0.4s ease;
}

@keyframes matchPulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.06); }
  100% { transform: scale(1); }
}

.card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(255, 255, 255, 0.08);
  opacity: 0;
  transition: opacity 0.2s;
}

.card:hover:not(.matched):not(.flipped)::after {
  opacity: 1;
}

@media (max-width: 400px) {
  .game {
    padding: 16px;
  }
  .board {
    gap: 8px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .btn {
    padding: 8px 14px;
    font-size: 0.95rem;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const boardEl = document.getElementById('gameBoard');
  const moveCountEl = document.getElementById('moveCount');
  const winMessageEl = document.getElementById('winMessage');
  const newGameBtn = document.getElementById('newGameBtn');

  let deck = [];
  let firstCard = null;
  let secondCard = null;
  let lockBoard = false;
  let moves = 0;
  let matchedPairs = 0;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function buildDeck() {
    const cards = [];
    COLORS.forEach((color, index) => {
      cards.push({ id: index, color });
      cards.push({ id: index, color });
    });
    return shuffle(cards);
  }

  function createCardElement(card, index) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'card';
    btn.dataset.id = card.id;
    btn.dataset.index = index;
    btn.style.setProperty('--card-color', card.color);
    btn.setAttribute('aria-label', 'Card ' + (index + 1) + ', hidden');
    btn.addEventListener('click', onCardClick);
    return btn;
  }

  function renderBoard() {
    boardEl.innerHTML = '';
    deck.forEach((card, index) => {
      boardEl.appendChild(createCardElement(card, index));
    });
  }

  function onCardClick(event) {
    const card = event.currentTarget;
    if (lockBoard) return;
    if (card.classList.contains('flipped') || card.classList.contains('matched')) return;

    flipCard(card);

    if (!firstCard) {
      firstCard = card;
    } else {
      secondCard = card;
      lockBoard = true;
      moves++;
      moveCountEl.textContent = moves;
      checkMatch();
    }
  }

  function flipCard(card) {
    card.classList.add('flipped');
    const color = card.style.getPropertyValue('--card-color');
    card.setAttribute('aria-label', 'Card ' + (Number(card.dataset.index) + 1) + ', revealed');
  }

  function unflipCard(card) {
    card.classList.remove('flipped');
    card.setAttribute('aria-label', 'Card ' + (Number(card.dataset.index) + 1) + ', hidden');
  }

  function checkMatch() {
    if (firstCard.dataset.id === secondCard.dataset.id) {
      firstCard.classList.add('matched');
      secondCard.classList.add('matched');
      firstCard.setAttribute('aria-label', 'Card ' + (Number(firstCard.dataset.index) + 1) + ', matched');
      secondCard.setAttribute('aria-label', 'Card ' + (Number(secondCard.dataset.index) + 1) + ', matched');
      matchedPairs++;
      resetTurn();
      if (matchedPairs === COLORS.length) {
        winMessageEl.hidden = false;
      }
    } else {
      setTimeout(() => {
        unflipCard(firstCard);
        unflipCard(secondCard);
        resetTurn();
      }, 800);
    }
  }

  function resetTurn() {
    firstCard = null;
    secondCard = null;
    lockBoard = false;
  }

  function newGame() {
    deck = buildDeck();
    moves = 0;
    matchedPairs = 0;
    firstCard = null;
    secondCard = null;
    lockBoard = false;
    moveCountEl.textContent = '0';
    winMessageEl.hidden = true;
    renderBoard();
  }

  newGameBtn.addEventListener('click', newGame);

  newGame();
})();
